import{_ as a,o as i,c as r,a6 as t,an as l,ao as n,ap as s}from"./chunks/framework.BfmC6wP_.js";const g=JSON.parse('{"title":"BreadCrumb Block","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/BreadCrumbBlock.md","filePath":"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/BreadCrumbBlock.md"}'),o={name:"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/BreadCrumbBlock.md"};function c(d,e,h,m,p,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="breadcrumb-block" tabindex="-1">BreadCrumb Block <a class="header-anchor" href="#breadcrumb-block" aria-label="Permalink to “BreadCrumb Block”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The BreadCrumb Block outputs a trail representing the current view (for example, Home / Parent / Child). It is a dynamic, server-rendered block, so no breadcrumb HTML is stored in post content.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h2><ul><li>Dynamic server-side rendering (PHP <code>render.php</code>)</li><li>Supports singular content, the posts index, search results, archives, and 404 pages</li><li>Includes ancestors for hierarchical posts and pages</li><li>Uses <code>/</code> as the separator</li><li>Renders the current item as plain text</li><li>Shows a static placeholder preview in the editor</li><li>RTL-compatible styles (separate compiled CSS)</li></ul><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to Use”">​</a></h2><p>Place the block near the top of templates or in a Header/Content template part to improve navigation clarity and orientation. It is especially useful for large sites with nested pages.</p><h3 id="using-breadcrumbs-to-navigate" tabindex="-1">Using Breadcrumbs to navigate <a class="header-anchor" href="#using-breadcrumbs-to-navigate" aria-label="Permalink to “Using Breadcrumbs to navigate”">​</a></h3><p><img src="'+l+'" alt="Using Breadcrumbs"></p><h2 id="editing-experience" tabindex="-1">Editing Experience <a class="header-anchor" href="#editing-experience" aria-label="Permalink to “Editing Experience”">​</a></h2><p>In the Site Editor or content editor, the block shows the static example Home / Parent / Child. The current context and hierarchy appear only on the front end. The block has no breadcrumb-specific settings. <img src="'+n+'" alt="Add a Breadcrumb Block"></p><h2 id="front-end-rendering" tabindex="-1">Front-End Rendering <a class="header-anchor" href="#front-end-rendering" aria-label="Permalink to “Front-End Rendering”">​</a></h2><p>For singular hierarchical content, the PHP render callback assembles:</p><ol><li>Home</li><li>Intermediate ancestors</li><li>The current item as plain text</li></ol><p>For non-hierarchical singular content, the posts index, search results, archives, and 404 pages, it renders Home followed by the current context. Home and ancestors are links; the current item is not linked. The breadcrumb is not displayed on the front page.</p><h2 id="usage-examples" tabindex="-1">Usage Examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to “Usage Examples”">​</a></h2><h3 id="add-to-a-template" tabindex="-1">Add to a Template <a class="header-anchor" href="#add-to-a-template" aria-label="Permalink to “Add to a Template”">​</a></h3><ol><li>Appearance &gt; Editor.</li><li>Open the relevant template or create a Template Part such as Header.</li><li>Insert “BreadCrumb” block below site header.</li><li>Save and view the template on the front end.</li></ol><h3 id="quick-demo-hierarchy" tabindex="-1">Quick Demo Hierarchy <a class="header-anchor" href="#quick-demo-hierarchy" aria-label="Permalink to “Quick Demo Hierarchy”">​</a></h3><p>Create three Pages:</p><ul><li>Grandparent (top level)</li><li>Parent (set Parent to Grandparent)</li><li>Child (set Parent to Parent) View Child page with the block placed in the Page template.</li></ul><p><img src="'+s+'" alt="Page Hierarchy"></p><h2 id="styling-customization-custom-css" tabindex="-1">Styling &amp; Customization (custom CSS) <a class="header-anchor" href="#styling-customization-custom-css" aria-label="Permalink to “Styling &amp; Customization (custom CSS)”">​</a></h2><ul><li>Target wrapper selector: <code>.dswp-block-breadcrumb__container</code></li><li>Separator element: <code>.dswp-breadcrumb-separator</code></li><li>Provide overrides in a theme stylesheet or a global style variation.</li><li>RTL adjustments handled by generated <code>style-index-rtl.css</code>.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to “Accessibility”">​</a></h2><ul><li>Uses a navigation landmark with an accessible label.</li><li>Each ancestor is a link; the current item is plain text.</li><li>Keep link text concise; page title changes automatically propagate.</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h2><p>Dynamic rendering avoids recalculating trails client-side. Minimal markup; styles are precompiled.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h2><ul><li>No built-in schema markup (can be added in theme if desired).</li><li>Archives show the current archive title but not a taxonomy ancestor path.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li>Avoid placing multiple breadcrumb blocks on the same template.</li><li>Keep divider style consistent site-wide.</li><li>Do not manually duplicate breadcrumb links in body content.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Breadcrumbs missing: Confirm the block is present in the template used by the current view.</li><li>Wrong hierarchy: Verify parent settings for each Page.</li><li>Breadcrumb absent on the front page: This is expected behavior.</li></ul>',34)])])}const k=a(o,[["render",c]]);export{g as __pageData,k as default};
